                    "sql": "create or replace table hox_db.maplemonk.HOX_ZEPTO_retailez_secondary_sales_consolidated as with skus as ( select distinct o.* from ( select replace(marketplace_sku,\'\`\',\'\') marketplace_sku ,replace(master_sku,\'\`\',\'\') master_sku ,row_number() over (partition by replace(marketplace_sku,\'\`\',\'\') order by 1) rw from HOX_DB.MAPLEMONK.sku_master )as o where rw=1 ), product_names as ( select distinct o.* from ( select trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_yfl_tax_sales union select trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_yfl_tax_returns union select trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_sales union select trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_returns union select \'YFL_\' || trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_yfl_tax_sales union select \'YFL_\' || trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_yfl_tax_returns union select \'YFL_\' || trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_sales union select \'YFL_\' || trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_returns )as o where 1= 1 QUALIFY row_number() over(partition by component_sku order by product_name) = 1 ) select o.*, coalesce(a.master_sku, o.sku_number) as sku, b.product_name from ( select date(date) as order_Date, case when \"Brand Name\" = \'YFL Home\' then \'YFL\' end as brand_name, \"SKU Number\" as sku_number, CITY, \'Zepto Secondary\' as marketplace, sum(\"Sales (Qty) - Units\") as quantity, sum(\"Gross Merchandise Value\") as Revenue from hox_db.maplemonk.HOX_Zepto_YFL_sales where \"Brand Name\" = \'YFL Home\' group by 1,2,3,4,5 union all select date(date) as order_Date, case when \"Brand Name\" = \'Cüraa\' then \'Sevenchef\' end as brand_name, \"SKU Number\" as sku_number, CITY, \'Zepto Secondary\' as marketplace, sum(\"Sales (Qty) - Units\") as quantity, sum(\"Gross Merchandise Value\") as Revenue from hox_db.maplemonk.HOX_ZEPTO_SEVENCHEF_SALES group by 1,2,3,4,5 union all SELECT CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', (starttime::TIMESTAMP))::date AS order_Date, \'Sevenchef\' as brand_name, asin as sku_number, null as CITY, \'RetailEz Secondary\' as marketplace, sum(ifnull(orderedunits,0)) quantity, sum(ifnull(orderedrevenue,0)) revenue from hox_db.maplemonk.hox_sevenchef_get_vendor_real_time_sales_report group by 1, 2, 3, 4, 5 ) as o left join skus a on lower(o.sku_number) = lower(a.marketplace_sku) left join product_names b on lower(coalesce(a.master_sku, o.sku_number)) = lower(b.component_sku);",
                    "transaction": true
